    private readonly EventListenerRegistry _eventListeners = new();

    /// <summary>
    /// on(type, callback) 的类型化重载（回调经共享跳板进入 C#，任意参数类型自动转换）
    /// </summary>
    public void On(string type, System.Action<global::HarmonyOS.ArkUI.ControllerAttachState> callback)
    {
        _eventListeners.Add((type, callback),
            args => callback((global::HarmonyOS.ArkUI.ControllerAttachState)NativeValue.ToInt(args[0])),
            js => NodeApi.CallMethodVoid(Handle, _on, type, js));
    }

    /// <summary>
    /// off(type)：移除该事件类型的全部回调
    /// </summary>
    public void Off(string type)
    {
        NodeApi.CallMethodVoid(Handle, _off, type);
    }

    /// <summary>
    /// off(type, callback)：解除订阅（按 handler 匹配）
    /// </summary>
    public void Off(string type, System.Action<global::HarmonyOS.ArkUI.ControllerAttachState> callback)
    {
        _eventListeners.Remove((type, callback), js => NodeApi.CallMethodVoid(Handle, _off, type, js));
    }

    /// <summary>
    /// 监听 controllerAttachStateChange 事件（对应 on/off）
    /// </summary>
    public event System.Action<global::HarmonyOS.ArkUI.ControllerAttachState> ControllerAttachStateChange
    {
        add
        {
            _eventListeners.Add(("controllerAttachStateChange", value),
                args => value((global::HarmonyOS.ArkUI.ControllerAttachState)NativeValue.ToInt(args[0])),
                js => NodeApi.CallMethodVoid(Handle, _on, "controllerAttachStateChange", js));
        }
        remove
        {
            _eventListeners.Remove(("controllerAttachStateChange", value), js => NodeApi.CallMethodVoid(Handle, _off, "controllerAttachStateChange", js));
        }
    }

}

/// <summary>
/// WebSchemeHandlerResponse 实例包装（@ohos 命名空间内嵌套类）。
/// 由 JsObject 持有 napi 强引用；Dispose 仅释放引用，JS 对象由 ArkTS GC 管理。
/// </summary>
public sealed partial class WebSchemeHandlerResponse : JsObject
